309	    pub(crate) fn new() -> anyhow::Result<Self> {
310	        let event_loop = EventLoop::try_new()?;
311	
312	        let (common, main_receiver, wake_receiver) = LinuxCommon::new(event_loop.get_signal());
313	
314	        let handle = event_loop.handle();
315	
316	        handle
317	            .insert_source(main_receiver, {
318	                let handle = handle.clone();
319	                move |event, _, _: &mut X11Client| {
320	                    if let calloop::channel::Event::Msg(runnable) = event {
321	                        // Insert the runnables as idle callbacks, so we make sure that user-input and X11
322	                        // events have higher priority and runnables are only worked off after the event
323	                        // callbacks.
324	                        handle.insert_idle(|client| {
325	                            let location = runnable.metadata().location;
326	                            let spawned = runnable.metadata().spawned;
327	                            profiler::update_running_task(spawned, location);
328	                            runnable.run();
329	                            profiler::save_task_timing();
330	
331	                            let xcb_connection = client.0.borrow().xcb_connection.clone();
332	                            client.process_x11_events(&xcb_connection).log_err();
333	                        });
334	                    }
335	                }
336	            })
337	            .map_err(|err| {
338	                anyhow!("Failed to initialize event loop handling of foreground tasks: {err:?}")
339	            })?;
340	
341	        handle
342	            .insert_source(wake_receiver, |event, _, client: &mut X11Client| {
343	                if let calloop::channel::Event::Msg(()) = event {
344	                    client.0.borrow_mut().common.handle_system_wake();
345	                }
346	            })
347	            .map_err(|err| {
348	                anyhow!("Failed to initialize event loop handling of wake events: {err:?}")
349	            })?;
350	
351	        let (xcb_connection, x_root_index) = XCBConnection::connect(None)?;
352	        xcb_connection.prefetch_extension_information(xkb::X11_EXTENSION_NAME)?;
353	        xcb_connection.prefetch_extension_information(randr::X11_EXTENSION_NAME)?;
354	        xcb_connection.prefetch_extension_information(render::X11_EXTENSION_NAME)?;
355	        xcb_connection.prefetch_extension_information(xinput::X11_EXTENSION_NAME)?;
356	
357	        // Announce to X server that XInput up to 2.4 is supported.
358	        // Version 2.4 is needed for gesture events (GesturePinchBegin/Update/End).
359	        // The server responds with the highest version it supports; if < 2.4,
360	        // we must not request gesture event masks in XISelectEvents.
361	        let xinput_version = get_reply(
362	            || "XInput XiQueryVersion failed",
363	            xcb_connection.xinput_xi_query_version(2, 4),
364	        )?;
365	        assert!(
366	            xinput_version.major_version >= 2,
367	            "XInput version >= 2 required."
368	        );
369	        let supports_xinput_gestures = xinput_version.major_version > 2
370	            || (xinput_version.major_version == 2 && xinput_version.minor_version >= 4);
371	        log::info!(
372	            "XInput version: {}.{}, gesture support: {}",
373	            xinput_version.major_version,
374	            xinput_version.minor_version,
375	            supports_xinput_gestures,
376	        );
377	
378	        let pointer_device_states =
379	            current_pointer_device_states(&xcb_connection, &BTreeMap::new()).unwrap_or_default();
380	
381	        let atoms = XcbAtoms::new(&xcb_connection)
382	            .context("Failed to get XCB atoms")?
383	            .reply()
384	            .context("Failed to get XCB atoms")?;
385	
386	        let root = xcb_connection.setup().roots[0].root;
387	        let compositor_present = check_compositor_present(&xcb_connection, root);
388	        let gtk_frame_extents_supported =
389	            check_gtk_frame_extents_supported(&xcb_connection, &atoms, root);
390	        let client_side_decorations_supported = compositor_present && gtk_frame_extents_supported;
391	        log::info!(
392	            "x11: compositor present: {}, gtk_frame_extents_supported: {}",
393	            compositor_present,
394	            gtk_frame_extents_supported
395	        );
396	
397	        let xkb = get_reply(
398	            || "Failed to initialize XKB extension",
399	            xcb_connection
400	                .xkb_use_extension(XKB_X11_MIN_MAJOR_XKB_VERSION, XKB_X11_MIN_MINOR_XKB_VERSION),
401	        )?;
402	        assert!(xkb.supported);
403	
404	        let events = xkb::EventType::STATE_NOTIFY
405	            | xkb::EventType::MAP_NOTIFY
406	            | xkb::EventType::NEW_KEYBOARD_NOTIFY;
407	        let map_notify_parts = xkb::MapPart::KEY_TYPES
408	            | xkb::MapPart::KEY_SYMS
409	            | xkb::MapPart::MODIFIER_MAP
410	            | xkb::MapPart::EXPLICIT_COMPONENTS
411	            | xkb::MapPart::KEY_ACTIONS
