415	        check_reply(
416	            || "Failed to select XKB events",
417	            xcb_connection.xkb_select_events(
418	                xkb::ID::USE_CORE_KBD.into(),
419	                0u8.into(),
420	                events,
421	                map_notify_parts,
422	                map_notify_parts,
423	                &xkb::SelectEventsAux::new(),
424	            ),
425	        )?;
426	
427	        let xkb_context = new_xkb_context()?;
428	        let xkb_device_id = xkbc::x11::get_core_keyboard_device_id(&xcb_connection);
429	        let xkb_state = {
430	            let xkb_keymap = xkbc::x11::keymap_new_from_device(
431	                &xkb_context,
432	                &xcb_connection,
433	                xkb_device_id,
434	                xkbc::KEYMAP_COMPILE_NO_FLAGS,
435	            );
436	            xkbc::x11::state_new_from_device(&xkb_keymap, &xcb_connection, xkb_device_id)
437	        };
438	        let compose_state = get_xkb_compose_state(&xkb_context);
439	        let layout_idx = xkb_state.serialize_layout(STATE_LAYOUT_EFFECTIVE);
440	        let layout_name = xkb_state
441	            .get_keymap()
442	            .layout_get_name(layout_idx)
443	            .to_string();
444	        let keyboard_layout = LinuxKeyboardLayout::new(layout_name.into());
445	
446	        let resource_database = x11rb::resource_manager::new_from_default(&xcb_connection)
447	            .context("Failed to create resource database")?;
448	        let scale_factor = get_scale_factor(&xcb_connection, &resource_database, x_root_index);
449	        let cursor_handle = cursor::Handle::new(&xcb_connection, x_root_index, &resource_database)
450	            .context("Failed to initialize cursor theme handler")?
451	            .reply()
452	            .context("Failed to initialize cursor theme handler")?;
453	
454	        let clipboard = Clipboard::new().context("Failed to initialize clipboard")?;
455	
456	        let screen = &xcb_connection.setup().roots[x_root_index];
457	        let compositor_gpu = detect_compositor_gpu(&xcb_connection, screen);
458	
459	        let xcb_connection = Rc::new(xcb_connection);
460	
461	        let ximc = X11rbClient::init(Rc::clone(&xcb_connection), x_root_index, None).ok();
462	        let xim_handler = if ximc.is_some() {
463	            Some(XimHandler::new())
464	        } else {
465	            None
466	        };
467	
468	        // Safety: Safe if xcb::Connection always returns a valid fd
469	        let fd = unsafe { FdWrapper::new(Rc::clone(&xcb_connection)) };
470	
471	        handle
472	            .insert_source(
473	                Generic::new_with_error::<EventHandlerError>(
474	                    fd,
475	                    calloop::Interest::READ,
476	                    calloop::Mode::Level,
477	                ),
478	                {
479	                    let xcb_connection = xcb_connection.clone();
480	                    move |_readiness, _, client| {
481	                        client.process_x11_events(&xcb_connection)?;
482	                        Ok(calloop::PostAction::Continue)
483	                    }
484	                },
485	            )
486	            .map_err(|err| anyhow!("Failed to initialize X11 event source: {err:?}"))?;
487	
488	        handle
489	            .insert_source(XDPEventSource::new(&common.background_executor), {
490	                move |event, _, client| match event {
491	                    XDPEvent::WindowAppearance(appearance) => {
492	                        client.with_common(|common| common.appearance = appearance);
493	                        for window in client.0.borrow_mut().windows.values_mut() {
494	                            window.window.set_appearance(appearance);
495	                        }
496	                    }
497	                    XDPEvent::ButtonLayout(layout_str) => {
498	                        let layout = WindowButtonLayout::parse(&layout_str)
499	                            .log_err()
500	                            .unwrap_or_else(WindowButtonLayout::linux_default);
501	                        client.with_common(|common| common.button_layout = layout);
502	                        for window in client.0.borrow_mut().windows.values_mut() {
503	                            window.window.set_button_layout();
504	                        }
505	                    }
506	                    XDPEvent::CursorTheme(_) | XDPEvent::CursorSize(_) => {
507	                        // noop, X11 manages this for us.
508	                    }
509	                }
510	            })
511	            .map_err(|err| anyhow!("Failed to initialize XDP event source: {err:?}"))?;
512	
513	        xcb_flush(&xcb_connection);
514	
515	        Ok(X11Client(Rc::new(RefCell::new(X11ClientState {
516	            modifiers: Modifiers::default(),
517	            capslock: Capslock::default(),
518	            last_modifiers_changed_event: Modifiers::default(),
519	            last_capslock_changed_event: Capslock::default(),
520	            event_loop: Some(event_loop),
521	            loop_handle: handle,
522	            common,
523	            last_click: Instant::now(),
524	            last_mouse_button: None,
525	            last_location: Point::new(px(0.0), px(0.0)),
526	            current_count: 0,
527	            pinch_scale: 1.0,
528	            gpu_context: Rc::new(RefCell::new(None)),
529	            compositor_gpu,
