536	            x_root_index,
537	            resource_database,
538	            atoms,
539	            windows: HashMap::default(),
540	            mouse_focused_window: None,
541	            keyboard_focused_window: None,
542	            xkb: xkb_state,
543	            keyboard_layout,
544	            ximc,
545	            xim_handler,
546	
547	            compose_state,
548	            pre_edit_text: None,
549	            pre_key_char_down: None,
550	            composing: false,
551	
