568	    pub fn process_x11_events(
569	        &self,
570	        xcb_connection: &XCBConnection,
571	    ) -> Result<(), EventHandlerError> {
572	        loop {
573	            let mut events = Vec::new();
574	            let mut windows_to_refresh = HashSet::new();
575	
576	            let mut last_key_release = None;
577	
578	            // event handlers for new keyboard / remapping refresh the state without using event
579	            // details, this deduplicates them.
580	            let mut last_keymap_change_event: Option<Event> = None;
581	
582	            loop {
583	                match xcb_connection.poll_for_event() {
584	                    Ok(Some(event)) => {
585	                        match event {
586	                            Event::Expose(expose_event) => {
587	                                windows_to_refresh.insert(expose_event.window);
588	                            }
589	                            Event::KeyRelease(_) => {
590	                                if let Some(last_keymap_change_event) =
591	                                    last_keymap_change_event.take()
592	                                {
593	                                    if let Some(last_key_release) = last_key_release.take() {
594	                                        events.push(last_key_release);
595	                                    }
596	                                    events.push(last_keymap_change_event);
597	                                }
598	
599	                                last_key_release = Some(event);
600	                            }
601	                            Event::KeyPress(key_press) => {
602	                                if let Some(last_keymap_change_event) =
603	                                    last_keymap_change_event.take()
604	                                {
605	                                    if let Some(last_key_release) = last_key_release.take() {
606	                                        events.push(last_key_release);
607	                                    }
608	                                    events.push(last_keymap_change_event);
609	                                }
610	
611	                                if let Some(Event::KeyRelease(key_release)) =
612	                                    last_key_release.take()
613	                                {
614	                                    // We ignore that last KeyRelease if it's too close to this KeyPress,
615	                                    // suggesting that it's auto-generated by X11 as a key-repeat event.
616	                                    if key_release.detail != key_press.detail
617	                                        || key_press.time.saturating_sub(key_release.time) > 20
618	                                    {
619	                                        events.push(Event::KeyRelease(key_release));
620	                                    }
621	                                }
622	                                events.push(Event::KeyPress(key_press));
623	                            }
624	                            Event::XkbNewKeyboardNotify(_) | Event::XkbMapNotify(_) => {
625	                                if let Some(release_event) = last_key_release.take() {
626	                                    events.push(release_event);
627	                                }
628	                                last_keymap_change_event = Some(event);
629	                            }
630	                            _ => {
631	                                if let Some(release_event) = last_key_release.take() {
632	                                    events.push(release_event);
633	                                }
634	                                events.push(event);
635	                            }
636	                        }
637	                    }
638	                    Ok(None) => {
639	                        break;
640	                    }
641	                    Err(err @ ConnectionError::IoError(..)) => {
642	                        return Err(EventHandlerError::from(err));
643	                    }
644	                    Err(err) => {
645	                        let err = handle_connection_error(err);
646	                        log::warn!("error while polling for X11 events: {err:?}");
647	                        break;
648	                    }
649	                }
650	            }
651	
652	            if let Some(release_event) = last_key_release.take() {
653	                events.push(release_event);
654	            }
655	            if let Some(keymap_change_event) = last_keymap_change_event.take() {
656	                events.push(keymap_change_event);
657	            }
658	
659	            if events.is_empty() && windows_to_refresh.is_empty() {
660	                break;
661	            }
662	
663	            for event in events.into_iter() {
664	                let mut state = self.0.borrow_mut();
665	                if !state.has_xim() {
666	                    drop(state);
667	                    self.handle_event(event);
668	                    continue;
669	                }
670	
671	                let Some((mut ximc, mut xim_handler)) = state.take_xim() else {
672	                    continue;
673	                };
674	                let xim_connected = xim_handler.connected;
675	                drop(state);
676	
677	                let xim_filtered = ximc.filter_event(&event, &mut xim_handler);
678	                let xim_callback_event = xim_handler.last_callback_event.take();
679	
680	                let mut state = self.0.borrow_mut();
681	                state.restore_xim(ximc, xim_handler);
682	                drop(state);
683	
684	                if let Some(event) = xim_callback_event {
685	                    self.handle_xim_callback_event(event);
686	                }
687	
688	                match xim_filtered {
689	                    Ok(handled) => {
690	                        if handled {
691	                            continue;
692	                        }
693	                        if xim_connected {
694	                            self.xim_handle_event(event);
695	                        } else {
696	                            self.handle_event(event);
697	                        }
698	                    }
699	                    Err(err) => {
700	                        // this might happen when xim server crashes on one of the events
701	                        // we do lose 1-2 keys when crash happens since there is no reliable way to get that info
702	                        // luckily, x11 sends us window not found error when xim server crashes upon further key press
703	                        // hence we fall back to handle_event
704	                        log::error!("XIMClientError: {}", err);
705	                        let mut state = self.0.borrow_mut();
706	                        state.take_xim();
707	                        drop(state);
708	                        self.handle_event(event);
709	                    }
710	                }
711	            }
712	
713	            for x_window in windows_to_refresh {
714	                let window = self
715	                    .0
716	                    .borrow()
717	                    .windows
718	                    .get(&x_window)
719	                    .and_then(|window| window.is_mapped.then(|| window.window.clone()));
720	                if let Some(window) = window {
721	                    window.refresh(RequestFrameOptions {
722	                        require_presentation: true,
723	                        force_render: false,
724	                    });
725	                }
726	            }
727	        }
728	        Ok(())
729	    }
