731	    pub fn enable_ime(&self) {
732	        let mut state = self.0.borrow_mut();
733	        if !state.has_xim() {
734	            return;
735	        }
736	
737	        let Some((mut ximc, xim_handler)) = state.take_xim() else {
738	            return;
739	        };
740	        let mut ic_attributes = ximc
741	            .build_ic_attributes()
742	            .push(AttributeName::InputStyle, InputStyle::PREEDIT_CALLBACKS)
743	            .push(AttributeName::ClientWindow, xim_handler.window)
744	            .push(AttributeName::FocusWindow, xim_handler.window);
745	
746	        let window_id = state.keyboard_focused_window;
747	        drop(state);
748	        if let Some(window_id) = window_id {
749	            let Some(window) = self.get_window(window_id) else {
750	                log::error!("Failed to get window for IME positioning");
751	                let mut state = self.0.borrow_mut();
752	                state.ximc = Some(ximc);
753	                state.xim_handler = Some(xim_handler);
754	                return;
755	            };
756	            if let Some(scaled_area) = window.get_ime_area() {
757	                ic_attributes =
758	                    ic_attributes.nested_list(xim::AttributeName::PreeditAttributes, |b| {
759	                        b.push(
760	                            xim::AttributeName::SpotLocation,
761	                            xim::Point {
762	                                x: u32::from(scaled_area.origin.x + scaled_area.size.width) as i16,
763	                                y: u32::from(scaled_area.origin.y + scaled_area.size.height) as i16,
764	                            },
765	                        );
766	                    });
767	            }
768	        }
769	        ximc.create_ic(xim_handler.im_id, ic_attributes.build())
770	            .ok();
771	        let mut state = self.0.borrow_mut();
772	        state.restore_xim(ximc, xim_handler);
773	    }
