775	    pub fn reset_ime(&self) {
776	        let mut state = self.0.borrow_mut();
777	        state.composing = false;
778	        if let Some(mut ximc) = state.ximc.take() {
779	            if let Some(xim_handler) = state.xim_handler.as_ref() {
780	                ximc.reset_ic(xim_handler.im_id, xim_handler.ic_id).ok();
781	            } else {
782	                log::error!("bug: xim handler not set in reset_ime");
783	            }
784	            state.ximc = Some(ximc);
785	        }
786	    }
