788	    pub(crate) fn get_window(&self, win: xproto::Window) -> Option<X11WindowStatePtr> {
789	        let state = self.0.borrow();
790	        state
791	            .windows
792	            .get(&win)
793	            .filter(|window_reference| !window_reference.window.state.borrow().destroyed)
794	            .map(|window_reference| window_reference.window.clone())
795	    }
