797	    fn handle_event(&self, event: Event) -> Option<()> {
798	        match event {
799	            Event::UnmapNotify(event) => {
800	                let mut state = self.0.borrow_mut();
801	                if let Some(window_ref) = state.windows.get_mut(&event.window) {
802	                    window_ref.is_mapped = false;
803	                }
804	                state.update_refresh_loop(event.window);
805	            }
806	            Event::MapNotify(event) => {
807	                let mut state = self.0.borrow_mut();
808	                if let Some(window_ref) = state.windows.get_mut(&event.window) {
809	                    window_ref.is_mapped = true;
810	                }
811	                state.update_refresh_loop(event.window);
812	            }
813	            Event::VisibilityNotify(event) => {
814	                let mut state = self.0.borrow_mut();
815	                if let Some(window_ref) = state.windows.get_mut(&event.window) {
816	                    window_ref.last_visibility = event.state;
817	                }
818	                state.update_refresh_loop(event.window);
819	            }
820	            Event::ClientMessage(event) => {
821	                let window = self.get_window(event.window)?;
822	                let [atom, arg1, arg2, arg3, arg4] = event.data.as_data32();
823	                let mut state = self.0.borrow_mut();
824	
825	                if atom == state.atoms.WM_DELETE_WINDOW && window.should_close() {
826	                    // window "x" button clicked by user
827	                    // Rest of the close logic is handled in drop_window()
828	                    drop(state);
829	                    window.close();
830	                    state = self.0.borrow_mut();
831	                } else if atom == state.atoms._NET_WM_SYNC_REQUEST {
832	                    window.state.borrow_mut().last_sync_counter =
833	                        Some(x11rb::protocol::sync::Int64 {
834	                            lo: arg2,
835	                            hi: arg3 as i32,
836	                        })
837	                }
838	
839	                if event.type_ == state.atoms.XdndEnter {
840	                    state.xdnd_state.other_window = atom;
841	                    if (arg1 & 0x1) == 0x1 {
842	                        state.xdnd_state.drag_type = xdnd_get_supported_atom(
843	                            &state.xcb_connection,
844	                            &state.atoms,
845	                            state.xdnd_state.other_window,
846	                        );
847	                    } else {
848	                        if let Some(atom) = [arg2, arg3, arg4]
849	                            .into_iter()
850	                            .find(|atom| xdnd_is_atom_supported(*atom, &state.atoms))
851	                        {
852	                            state.xdnd_state.drag_type = atom;
