1820	    fn window_stack(&self) -> Option<Vec<AnyWindowHandle>> {
1821	        let state = self.0.borrow();
1822	        let root = state.xcb_connection.setup().roots[state.x_root_index].root;
1823	
1824	        let reply = state
1825	            .xcb_connection
1826	            .get_property(
1827	                false,
1828	                root,
1829	                state.atoms._NET_CLIENT_LIST_STACKING,
1830	                xproto::AtomEnum::WINDOW,
1831	                0,
1832	                u32::MAX,
1833	            )
1834	            .ok()?
1835	            .reply()
1836	            .ok()?;
1837	
1838	        let window_ids = reply
1839	            .value
1840	            .chunks_exact(4)
1841	            .filter_map(|chunk| chunk.try_into().ok().map(u32::from_ne_bytes))
1842	            .collect::<Vec<xproto::Window>>();
1843	
1844	        let mut handles = Vec::new();
1845	
1846	        // We need to reverse, since _NET_CLIENT_LIST_STACKING has
1847	        // a back-to-front order.
1848	        // See: https://specifications.freedesktop.org/wm-spec/1.3/ar01s03.html
1849	        for window_ref in window_ids
1850	            .iter()
1851	            .rev()
1852	            .filter_map(|&win| state.windows.get(&win))
1853	        {
1854	            if !window_ref.window.state.borrow().destroyed {
1855	                handles.push(window_ref.handle());
1856	            }
1857	        }
1858	
1859	        Some(handles)
1860	    }
