1898	    fn update_refresh_loop(&mut self, x_window: xproto::Window) {
1899	        let Some(window_ref) = self.windows.get_mut(&x_window) else {
1900	            return;
1901	        };
1902	        let is_visible = window_ref.is_mapped
1903	            && !matches!(window_ref.last_visibility, Visibility::FULLY_OBSCURED);
1904	        match (is_visible, window_ref.refresh_state.take()) {
1905	            (false, refresh_state @ Some(RefreshState::Hidden { .. }))
1906	            | (false, refresh_state @ None)
1907	            | (true, refresh_state @ Some(RefreshState::PeriodicRefresh { .. })) => {
1908	                window_ref.refresh_state = refresh_state;
1909	            }
1910	            (
1911	                false,
1912	                Some(RefreshState::PeriodicRefresh {
1913	                    refresh_rate,
1914	                    event_loop_token,
1915	                }),
1916	            ) => {
1917	                self.loop_handle.remove(event_loop_token);
1918	                window_ref.refresh_state = Some(RefreshState::Hidden { refresh_rate });
1919	            }
1920	            (true, Some(RefreshState::Hidden { refresh_rate })) => {
1921	                let event_loop_token = self.start_refresh_loop(x_window, refresh_rate);
1922	                let Some(window_ref) = self.windows.get_mut(&x_window) else {
1923	                    return;
1924	                };
1925	                window_ref.refresh_state = Some(RefreshState::PeriodicRefresh {
1926	                    refresh_rate,
1927	                    event_loop_token,
1928	                });
1929	            }
1930	            (true, None) => {
1931	                let Some(screen_resources) = get_reply(
1932	                    || "Failed to get screen resources",
1933	                    self.xcb_connection
1934	                        .randr_get_screen_resources_current(x_window),
1935	                )
1936	                .log_err() else {
1937	                    return;
1938	                };
1939	
1940	                // Ideally this would be re-queried when the window changes screens, but there
1941	                // doesn't seem to be an efficient / straightforward way to do this. Should also be
1942	                // updated when screen configurations change.
1943	                let mode_info = screen_resources.crtcs.iter().find_map(|crtc| {
1944	                    let crtc_info = self
1945	                        .xcb_connection
1946	                        .randr_get_crtc_info(*crtc, x11rb::CURRENT_TIME)
1947	                        .ok()?
1948	                        .reply()
1949	                        .ok()?;
1950	
1951	                    screen_resources
1952	                        .modes
1953	                        .iter()
1954	                        .find(|m| m.id == crtc_info.mode)
1955	                });
1956	                let refresh_rate = match mode_info {
1957	                    Some(mode_info) => mode_refresh_rate(mode_info),
1958	                    None => {
1959	                        log::error!(
1960	                            "Failed to get screen mode info from xrandr, \
1961	                            defaulting to 60hz refresh rate."
1962	                        );
1963	                        Duration::from_micros(1_000_000 / 60)
1964	                    }
1965	                };
1966	
1967	                let event_loop_token = self.start_refresh_loop(x_window, refresh_rate);
1968	                let Some(window_ref) = self.windows.get_mut(&x_window) else {
1969	                    return;
1970	                };
1971	                window_ref.refresh_state = Some(RefreshState::PeriodicRefresh {
1972	                    refresh_rate,
1973	                    event_loop_token,
1974	                });
1975	            }
1976	        }
1977	    }
