1979	    #[must_use]
1980	    fn start_refresh_loop(
1981	        &self,
1982	        x_window: xproto::Window,
1983	        refresh_rate: Duration,
1984	    ) -> RegistrationToken {
1985	        self.loop_handle
1986	            .insert_source(calloop::timer::Timer::immediate(), {
1987	                move |mut instant, (), client| {
1988	                    let xcb_connection = {
1989	                        let mut state = client.0.borrow_mut();
1990	                        let xcb_connection = state.xcb_connection.clone();
1991	                        if let Some(window) = state.windows.get_mut(&x_window) {
1992	                            let force_render = std::mem::take(
1993	                                &mut window.window.state.borrow_mut().force_render_after_recovery,
1994	                            );
1995	                            let window = window.window.clone();
1996	                            drop(state);
1997	                            window.refresh(RequestFrameOptions {
1998	                                require_presentation: false,
