2017	    fn get_cursor_icon(&mut self, style: CursorStyle) -> Option<xproto::Cursor> {
2018	        if let Some(cursor) = self.cursor_cache.get(&style) {
2019	            return *cursor;
2020	        }
2021	
2022	        let result = 'outer: {
2023	            let mut errors = String::new();
2024	            let cursor_icon_names = cursor_style_to_icon_names(style);
2025	            for cursor_icon_name in cursor_icon_names {
2026	                match self
2027	                    .cursor_handle
2028	                    .load_cursor(&self.xcb_connection, cursor_icon_name)
2029	                {
2030	                    Ok(loaded_cursor) => {
2031	                        if loaded_cursor != x11rb::NONE {
2032	                            break 'outer Ok(loaded_cursor);
2033	                        }
2034	                    }
2035	                    Err(err) => {
2036	                        errors.push_str(&err.to_string());
2037	                        errors.push('\n');
2038	                    }
2039	                }
2040	            }
2041	            if errors.is_empty() {
2042	                Err(anyhow!(
2043	                    "errors while loading cursor icons {:?}:\n{}",
2044	                    cursor_icon_names,
2045	                    errors
2046	                ))
2047	            } else {
2048	                Err(anyhow!("did not find cursor icons {:?}", cursor_icon_names))
2049	            }
2050	        };
2051	
2052	        let cursor = match result {
2053	            Ok(cursor) => Some(cursor),
2054	            Err(err) => {
2055	                match self
2056	                    .cursor_handle
2057	                    .load_cursor(&self.xcb_connection, DEFAULT_CURSOR_ICON_NAME)
2058	                {
2059	                    Ok(default) => {
2060	                        log_cursor_icon_warning(err.context(format!(
2061	                            "X11: error loading cursor icon, falling back on default icon '{}'",
2062	                            DEFAULT_CURSOR_ICON_NAME
2063	                        )));
2064	                        Some(default)
2065	                    }
2066	                    Err(default_err) => {
2067	                        log_cursor_icon_warning(err.context(default_err).context(format!(
2068	                            "X11: error loading default cursor fallback '{}'",
2069	                            DEFAULT_CURSOR_ICON_NAME
2070	                        )));
2071	                        None
2072	                    }
2073	                }
2074	            }
2075	        };
2076	
2077	        self.cursor_cache.insert(style, cursor);
2078	        cursor
2079	    }
