2149	// Adapted from:
2150	// https://docs.rs/winit/0.29.11/src/winit/platform_impl/linux/x11/monitor.rs.html#103-111
2151	pub fn mode_refresh_rate(mode: &randr::ModeInfo) -> Duration {
2152	    if mode.dot_clock == 0 || mode.htotal == 0 || mode.vtotal == 0 {
2153	        return Duration::from_millis(16);
2154	    }
2155	
2156	    let millihertz = mode.dot_clock as u64 * 1_000 / (mode.htotal as u64 * mode.vtotal as u64);
2157	    let micros = 1_000_000_000 / millihertz;
2158	    log::info!("Refreshing every {}ms", micros / 1_000);
2159	    Duration::from_micros(micros)
2160	}
