2189	fn check_compositor_present(xcb_connection: &XCBConnection, root: xproto::Window) -> bool {
2190	    // Method 1: Check for _NET_WM_CM_S{root}
2191	    let atom_name = format!("_NET_WM_CM_S{}", root);
2192	    let atom1 = get_reply(
2193	        || format!("Failed to intern {atom_name}"),
2194	        xcb_connection.intern_atom(false, atom_name.as_bytes()),
2195	    );
2196	    let method1 = match atom1.log_with_level(Level::Debug) {
2197	        Some(reply) if reply.atom != x11rb::NONE => {
2198	            let atom = reply.atom;
2199	            get_reply(
2200	                || format!("Failed to get {atom_name} owner"),
2201	                xcb_connection.get_selection_owner(atom),
2202	            )
2203	            .map(|reply| reply.owner != 0)
2204	            .log_with_level(Level::Debug)
2205	            .unwrap_or(false)
2206	        }
2207	        _ => false,
2208	    };
2209	
2210	    // Method 2: Check for _NET_WM_CM_OWNER
2211	    let atom_name = "_NET_WM_CM_OWNER";
2212	    let atom2 = get_reply(
2213	        || format!("Failed to intern {atom_name}"),
2214	        xcb_connection.intern_atom(false, atom_name.as_bytes()),
2215	    );
2216	    let method2 = match atom2.log_with_level(Level::Debug) {
2217	        Some(reply) if reply.atom != x11rb::NONE => {
2218	            let atom = reply.atom;
2219	            get_reply(
2220	                || format!("Failed to get {atom_name}"),
2221	                xcb_connection.get_property(false, root, atom, xproto::AtomEnum::WINDOW, 0, 1),
2222	            )
2223	            .map(|reply| reply.value_len > 0)
2224	            .unwrap_or(false)
2225	        }
2226	        _ => return false,
2227	    };
2228	
2229	    // Method 3: Check for _NET_SUPPORTING_WM_CHECK
2230	    let atom_name = "_NET_SUPPORTING_WM_CHECK";
2231	    let atom3 = get_reply(
2232	        || format!("Failed to intern {atom_name}"),
2233	        xcb_connection.intern_atom(false, atom_name.as_bytes()),
2234	    );
2235	    let method3 = match atom3.log_with_level(Level::Debug) {
2236	        Some(reply) if reply.atom != x11rb::NONE => {
2237	            let atom = reply.atom;
2238	            get_reply(
2239	                || format!("Failed to get {atom_name}"),
2240	                xcb_connection.get_property(false, root, atom, xproto::AtomEnum::WINDOW, 0, 1),
2241	            )
2242	            .map(|reply| reply.value_len > 0)
2243	            .unwrap_or(false)
2244	        }
2245	        _ => return false,
2246	    };
2247	
2248	    log::debug!(
2249	        "Compositor detection: _NET_WM_CM_S?={}, _NET_WM_CM_OWNER={}, _NET_SUPPORTING_WM_CHECK={}",
2250	        method1,
2251	        method2,
2252	        method3
2253	    );
2254	
2255	    method1 || method2 || method3
