2369	/// Recomputes `pointer_device_states` by querying all pointer devices.
2370	/// When a device is present in `scroll_values_to_preserve`, its value for `ScrollAxisState.scroll_value` is used.
2371	fn current_pointer_device_states(
2372	    xcb_connection: &XCBConnection,
2373	    scroll_values_to_preserve: &BTreeMap<xinput::DeviceId, PointerDeviceState>,
2374	) -> Option<BTreeMap<xinput::DeviceId, PointerDeviceState>> {
2375	    let devices_query_result = get_reply(
2376	        || "Failed to query XInput devices",
2377	        xcb_connection.xinput_xi_query_device(XINPUT_ALL_DEVICES),
2378	    )
2379	    .log_err()?;
2380	
2381	    let mut pointer_device_states = BTreeMap::new();
2382	    pointer_device_states.extend(
2383	        devices_query_result
2384	            .infos
2385	            .iter()
2386	            .filter(|info| is_pointer_device(info.type_))
2387	            .filter_map(|info| {
2388	                let scroll_data = info
2389	                    .classes
2390	                    .iter()
2391	                    .filter_map(|class| class.data.as_scroll())
2392	                    .copied()
2393	                    .rev()
2394	                    .collect::<Vec<_>>();
2395	                let old_state = scroll_values_to_preserve.get(&info.deviceid);
2396	                let old_horizontal = old_state.map(|state| &state.horizontal);
2397	                let old_vertical = old_state.map(|state| &state.vertical);
2398	                let horizontal = scroll_data
2399	                    .iter()
2400	                    .find(|data| data.scroll_type == xinput::ScrollType::HORIZONTAL)
2401	                    .map(|data| scroll_data_to_axis_state(data, old_horizontal));
2402	                let vertical = scroll_data
2403	                    .iter()
2404	                    .find(|data| data.scroll_type == xinput::ScrollType::VERTICAL)
2405	                    .map(|data| scroll_data_to_axis_state(data, old_vertical));
2406	                if horizontal.is_none() && vertical.is_none() {
2407	                    None
2408	                } else {
2409	                    Some((
2410	                        info.deviceid,
2411	                        PointerDeviceState {
2412	                            horizontal: horizontal.unwrap_or_else(Default::default),
2413	                            vertical: vertical.unwrap_or_else(Default::default),
2414	                        },
2415	                    ))
2416	                }
2417	            }),
2418	    );
2419	    if pointer_device_states.is_empty() {
2420	        log::error!("Found no xinput mouse pointers.");
2421	    }
2422	    Some(pointer_device_states)
2423	}
