2530	fn get_scale_factor(
2531	    connection: &XCBConnection,
2532	    resource_database: &Database,
2533	    screen_index: usize,
2534	) -> f32 {
2535	    let env_dpi = std::env::var(GPUI_X11_SCALE_FACTOR_ENV)
2536	        .ok()
2537	        .map(|var| {
2538	            if var.to_lowercase() == "randr" {
2539	                DpiMode::Randr
2540	            } else if let Ok(scale) = var.parse::<f32>() {
2541	                if valid_scale_factor(scale) {
2542	                    DpiMode::Scale(scale)
2543	                } else {
2544	                    panic!(
2545	                        "`{}` must be a positive normal number or `randr`. Got `{}`",
2546	                        GPUI_X11_SCALE_FACTOR_ENV, var
2547	                    );
2548	                }
2549	            } else if var.is_empty() {
2550	                DpiMode::NotSet
2551	            } else {
2552	                panic!(
2553	                    "`{}` must be a positive number or `randr`. Got `{}`",
2554	                    GPUI_X11_SCALE_FACTOR_ENV, var
2555	                );
2556	            }
2557	        })
2558	        .unwrap_or(DpiMode::NotSet);
2559	
2560	    match env_dpi {
2561	        DpiMode::Scale(scale) => {
2562	            log::info!(
2563	                "Using scale factor from {}: {}",
2564	                GPUI_X11_SCALE_FACTOR_ENV,
2565	                scale
2566	            );
2567	            return scale;
2568	        }
2569	        DpiMode::Randr => {
2570	            if let Some(scale) = get_randr_scale_factor(connection, screen_index) {
2571	                log::info!(
2572	                    "Using RandR scale factor from {}=randr: {}",
2573	                    GPUI_X11_SCALE_FACTOR_ENV,
2574	                    scale
2575	                );
2576	                return scale;
2577	            }
2578	            log::warn!("Failed to calculate RandR scale factor, falling back to default");
2579	            return 1.0;
2580	        }
2581	        DpiMode::NotSet => {}
2582	    }
2583	
2584	    // TODO: Use scale factor from XSettings here
2585	
2586	    if let Some(dpi) = resource_database
2587	        .get_value::<f32>("Xft.dpi", "Xft.dpi")
2588	        .ok()
2589	        .flatten()
2590	    {
2591	        let scale = dpi / 96.0; // base dpi
2592	        log::info!("Using scale factor from Xft.dpi: {}", scale);
2593	        return scale;
2594	    }
2595	
2596	    if let Some(scale) = get_randr_scale_factor(connection, screen_index) {
2597	        log::info!("Using RandR scale factor: {}", scale);
2598	        return scale;
2599	    }
2600	
2601	    log::info!("Using default scale factor: 1.0");
2602	    1.0
2603	}
2604	
2605	fn get_randr_scale_factor(connection: &XCBConnection, screen_index: usize) -> Option<f32> {
2606	    let root = connection.setup().roots.get(screen_index)?.root;
2607	
2608	    let version_cookie = connection.randr_query_version(1, 6).ok()?;
2609	    let version_reply = version_cookie.reply().ok()?;
2610	    if version_reply.major_version < 1
2611	        || (version_reply.major_version == 1 && version_reply.minor_version < 5)
2612	    {
2613	        return legacy_get_randr_scale_factor(connection, root); // for randr <1.5
2614	    }
2615	
2616	    let monitors_cookie = connection.randr_get_monitors(root, true).ok()?; // true for active only
2617	    let monitors_reply = monitors_cookie.reply().ok()?;
2618	
2619	    let mut fallback_scale: Option<f32> = None;
2620	    for monitor in monitors_reply.monitors {
2621	        if monitor.width_in_millimeters == 0 || monitor.height_in_millimeters == 0 {
2622	            continue;
2623	        }
2624	        let scale_factor = get_dpi_factor(
2625	            (monitor.width as u32, monitor.height as u32),
2626	            (
2627	                monitor.width_in_millimeters as u64,
2628	                monitor.height_in_millimeters as u64,
2629	            ),
2630	        );
2631	        if monitor.primary {
2632	            return Some(scale_factor);
2633	        } else if fallback_scale.is_none() {
2634	            fallback_scale = Some(scale_factor);
2635	        }
2636	    }
2637	
2638	    fallback_scale
2639	}
2640	
2641	fn legacy_get_randr_scale_factor(connection: &XCBConnection, root: u32) -> Option<f32> {
2642	    let primary_cookie = connection.randr_get_output_primary(root).ok()?;
2643	    let primary_reply = primary_cookie.reply().ok()?;
2644	    let primary_output = primary_reply.output;
2645	
2646	    let primary_output_cookie = connection
2647	        .randr_get_output_info(primary_output, x11rb::CURRENT_TIME)
2648	        .ok()?;
